command:
$ErrorActionPreference = 'Stop'
$baseSha = '0a0ffcfecab88d692e7a5ab94f42108a7099c0d0'
$branch = 'issue-416-gemini-knowledge-consolidation-eval'
$failed = $false
function Invoke-Checked([string]$Label, [scriptblock]$Action) {
