  if ($LASTEXITCODE -ne 0) { throw 'Unable to checkout PR branch head' }
  @'
from pathlib import Path

tool = Path('project_sources/agent_runtime/tools/evaluate_gemini_knowledge_consolidation.py')
text = tool.read_text(encoding='utf-8')
old = """    benefits = [
        (
            f'Candidate reduces runtime Knowledge files from {active_count} to '
            f'{candidate_count} without changing the canonical atomic sources.'
        ),
        'Every candidate source boundary retains id, canonical path, Git blob SHA, SHA-256, and byte count.',
"""
new = """    if baseline_errors:
        file_count_benefit = (
            'Candidate file-count reduction is not claimed because active '
            'projection validation did not pass.'
        )
    elif reduction_count > 0:
        file_count_benefit = (
            f'Candidate reduces runtime Knowledge files from {active_count} to '
            f'{candidate_count} without changing the canonical atomic sources.'
        )
    else:
        file_count_benefit = (
            f'Candidate does not reduce runtime Knowledge files '
            f'({active_count} active; {candidate_count} candidate) while '
            'leaving the canonical atomic sources unchanged.'
        )
    benefits = [
        file_count_benefit,
        'Every candidate source boundary retains id, canonical path, Git blob SHA, SHA-256, and byte count.',
"""
if text.count(old) != 1:
    raise SystemExit(f'expected one benefits block, found {text.count(old)}')
text = text.replace(old, new, 1)
tool.write_text(text, encoding='utf-8')

test = Path('project_sources/agent_runtime/tests/evaluate_gemini_knowledge_consolidation_selftest.py')
t = test.read_text(encoding='utf-8')
old_clean = "        self.assertEqual(report['candidate']['attachment_reduction_count'], 1)\n        self.assertTrue(report['candidate']['exact_source_coverage'])"
new_clean = "        self.assertEqual(report['candidate']['attachment_reduction_count'], 1)\n        self.assertIn('reduces runtime Knowledge files from 4 to 3', report['benefits'][0])\n        self.assertTrue(report['candidate']['exact_source_coverage'])"
if t.count(old_clean) != 1:
    raise SystemExit(f'expected one clean-benefit insertion point, found {t.count(old_clean)}')
t = t.replace(old_clean, new_clean, 1)
old_fail = "        self.assertEqual(report['candidate']['attachment_reduction_percent'], 0.0)\n\n    def test_corrupt_candidate_recovery_is_rejected"
new_fail = "        self.assertEqual(report['candidate']['attachment_reduction_percent'], 0.0)\n        self.assertIn('file-count reduction is not claimed', report['benefits'][0])\n\n    def test_corrupt_candidate_recovery_is_rejected"
if t.count(old_fail) != 1:
    raise SystemExit(f'expected one failure-benefit insertion point, found {t.count(old_fail)}')
t = t.replace(old_fail, new_fail, 1)
test.write_text(t, encoding='utf-8')
'@ | python -
  if ($LASTEXITCODE -ne 0) { throw 'Failure-report hardening edit failed' }
  git diff --check
  if ($LASTEXITCODE -ne 0) { throw 'git diff --check failed' }
  git add project_sources/agent_runtime/tools/evaluate_gemini_knowledge_consolidation.py project_sources/agent_runtime/tests/evaluate_gemini_knowledge_consolidation_selftest.py
  git diff --cached --quiet
  if ($LASTEXITCODE -eq 0) { throw 'Failure-report hardening produced no staged changes' }
  git -c user.name='Malware Devil' -c user.email='34285973+malwaredevil@users.noreply.github.com' commit -m 'Keep failed evaluation metrics honest'
  if ($LASTEXITCODE -ne 0) { throw 'Failure-report hardening commit failed' }
  $testedSha = (git rev-parse HEAD).Trim()
  Write-Host "tested_branch_head=$testedSha"
  Invoke-Checked 'Compile evaluator and tests' { python -m py_compile project_sources/agent_runtime/tools/evaluate_gemini_knowledge_consolidation.py project_sources/agent_runtime/tests/evaluate_gemini_knowledge_consolidation_selftest.py project_sources/agent_runtime/tests/project_agent_knowledge_selftest.py }
  Invoke-Checked 'Standalone Gemini consolidation evaluator self-tests' { python project_sources/agent_runtime/tests/evaluate_gemini_knowledge_consolidation_selftest.py }
  Invoke-Checked 'Integrated governed Knowledge self-tests' { python project_sources/agent_runtime/tests/project_agent_knowledge_selftest.py }
  Invoke-Checked '1 Shared source contract' { python project_sources/agent_runtime/tools/validate_shared_agent_source_contract.py }
  Invoke-Checked '2 Shared source contract self-tests' { python project_sources/agent_runtime/tests/validate_shared_agent_source_contract_selftest.py }
  Invoke-Checked '3 Behavior adapter materialization check' { python project_sources/agent_runtime/tools/materialize_agent_behavior_adapters.py --check }
  Invoke-Checked '4 Behavior adapter self-tests' { python project_sources/agent_runtime/tests/materialize_agent_behavior_adapters_selftest.py }
  Invoke-Checked '5 Knowledge projection check' { python project_sources/agent_runtime/tools/project_agent_knowledge.py --check }
  Invoke-Checked '6 Knowledge projection plus consolidation self-tests' { python project_sources/agent_runtime/tests/project_agent_knowledge_selftest.py }
  Invoke-Checked '7 OpenAI DCOIR package check' { python project_sources/agent_runtime/tools/build_openai_dcoir_analyst.py --check }
  Invoke-Checked '8 OpenAI DCOIR package self-tests' { python project_sources/agent_runtime/tests/build_openai_dcoir_analyst_selftest.py }
